/* ---- integrations/pdp-links.js ---- */
/* NUDGE interactive website: PDP integration. Binds the PDP wireframe to /products/:handle. The wireframe is ONE product page (Tinted Moisturiser: its gallery, description, FAQ and
   reviews slot). For any other product this file changes ONLY: title, price (and compare-at), breadcrumb, document title, and hides the shade and size pickers when the product has none
   (the picker would otherwise demand a shade before "Add to bag"). Everything else stays the sample content and is listed as a limitation.
   Add to bag: the page's own busy then "Added" sequence runs; when it reaches "Added" the line (product, quantity, shade, size) is written to the shared cart. "Add selected to bag" in
   Complete your routine adds the checked products. Related products and "View bag" are resolved by the route resolver.
   In Shopify: product.selected_or_first_available_variant, the product form posting to /cart/add.js, and complementary/related recommendations. */
(function (g) {
  'use strict';
  var NS = g.NudgeSite;
  function money(n) { return '$' + n.toFixed(2); }
  function $(id) { return document.getElementById(id); }
  function txt(id) { var e = $(id); return e ? e.textContent.trim() : ''; }
  /* The shared currency script (currency.js) rewrites "$32.00" into the chosen market's currency in the same nodes. Comparing against the raw "$" text would make the two
     observers undo each other forever, so a node counts as correct when it shows EITHER the base text or that text as currency.js would show it. */
  function shown(n) {
    var m = g.NudgeMarket ? g.NudgeMarket.markets.filter(function (x) { return x.cur === g.NudgeMarket.current(); })[0] : null;
    if (!m || m.rate === 1) return money(n);
    return new Intl.NumberFormat(m.loc, { style: 'currency', currency: m.cur, minimumFractionDigits: m.dec, maximumFractionDigits: m.dec }).format(n * m.rate);
  }
  function put(el, n, prefix) {
    if (!el) return; var t = el.textContent.trim(), base = (prefix || '') + money(n), conv = (prefix || '') + shown(n);
    if (t !== base && t !== conv) el.textContent = base;
  }
  function bindPrice(p) {
    function apply() {
      var cur = $('pr-cur'), cmp = $('pr-cmp'), sv = $('pr-save'), unit = $('pr-unit'), sa = $('sa-price'), has = p.compare > p.price;
      put(cur, p.price); put(sa, p.price);
      if (cmp) { if (has) put(cmp, p.compare); if (cmp.hidden === has) cmp.hidden = !has; }
      if (sv) { if (sv.hidden === has) sv.hidden = !has; if (has) put(sv, p.compare - p.price, 'Save '); }
      if (unit && !unit.hidden) unit.hidden = true;
    }
    apply();
    ['pr-cur', 'pr-cmp', 'pr-save', 'sa-price'].forEach(function (id) { var e = $(id); if (e) new MutationObserver(apply).observe(e, { childList: true, characterData: true, subtree: true, attributes: true, attributeFilter: ['hidden'] }); });
  }
  NS.integrations.product = function () {
    var q = new URLSearchParams(g.location.search), h = q.get('p') || 'tinted-moisturiser', p = NS.products.byHandle(h);
    if (!p) { NS.go('/404'); return; }
    NS.store.get().last.product = h; NS.store.save();
    var coll = NS.collections.get(p.group) || NS.collections.get('skin');
    NS.breadcrumbs.update([{ label: 'Home', route: '/' }, { label: coll.title, route: '/collections/' + coll.handle }, { label: p.name, route: '/products/' + h }]);
    document.title = p.name + ' | NUDGE';
    if (h !== 'tinted-moisturiser') {
      var t = $('p-title'); if (t) t.textContent = p.name; bindPrice(p);
      var early = document.getElementById('ix-early-pdp'); if (early) early.remove(); /* shown again below only where the product needs it */
      if (!p.shades.length) { if (g.NudgePDP && g.NudgePDP.pick) g.NudgePDP.pick(0); var sg = $('shade-tiles'); sg = sg && (sg.closest('fieldset') || sg.parentElement); if (sg) sg.hidden = true; }
      var sz = $('size-opts'); if (sz) { var zg = sz.closest('fieldset') || sz.parentElement; if (zg) zg.hidden = true; }
    }
    if (p.sold) { var a = $('atc'); if (a) { a.disabled = true; var l = $('atc-label'); if (l) l.textContent = 'Sold out'; } }
    /* add to bag: act when the page's own sequence reaches "Added" */
    var lab = $('atc-label'), was = lab ? lab.textContent : '';
    if (lab) new MutationObserver(function () {
      var now = lab.textContent; if (/^Added/.test(now) && !/^Added/.test(was)) {
        var qty = parseInt((($('q-input') || {}).value), 10) || 1, r = NS.cart.add(h, { qty: qty, shade: txt('shade-name'), size: txt('size-name') });
        if (r.capped) NS.notify('Quantity limited to what is in stock.', { kind: 'info' });
      } was = now;
    }).observe(lab, { childList: true, characterData: true, subtree: true });
    var ra = $('routine-add');
    if (ra) ra.addEventListener('click', function () {
      var n = 0; [].forEach.call(document.querySelectorAll('#routine-list input[type=checkbox]:checked'), function (c) {
        var pr = NS.nav.productIn(c.getAttribute('aria-label') || (c.closest('li') || c).textContent); if (pr && NS.cart.add(pr.handle, { qty: 1 }).ok) n++;
      });
    });
  };
})(window);

;
/* ---- integrations/cart-links.js ---- */
/* NUDGE interactive website: Cart page and Cart drawer page integration. Both wireframes already render lines, quantity, remove, undo, free-shipping progress and totals through window.NudgeCart.
   This file makes them show the SHARED cart instead of their sample states (NudgeCart.set is wrapped so the page's own render shows the shared lines), writes edits back, and turns Checkout
   into a clear "not simulated" notice. Continue shopping, empty-state chips and product names are resolved by the route resolver. The order note is kept in the shared state.
   The wireframes' review-state buttons (Multi, One, Free, Long, Empty) still work as before but are sample data and do not write to the shared cart.
   In Shopify: /cart.js for the lines, /cart/change.js for quantity and remove, cart attributes for the note, and Shopify Checkout for payment (never simulated here). */
(function (g) {
  'use strict';
  var NS = g.NudgeSite;
  function $(id) { return document.getElementById(id); }
  function boot(root, stateFn, checkoutIds) {
    var C = g.NudgeCart; if (!C || !stateFn) return;
    NS.cart.hookNudge(C); NS.cart.registerCatalogue(C); NS.cart.bindRoot(C, root);
    C.pushShared(function () { stateFn('multi'); });
    checkoutIds.forEach(function (id) { var b = $(id); if (b && !b.__ix) { b.__ix = 1; b.addEventListener('click', function () { NS.unsupported('checkout'); }); } });
    document.addEventListener('nudge:cart', function (e) { if (e.detail && e.detail.action === 'pull') return; C.pushShared(function () { stateFn('multi'); }); });
  }
  NS.integrations.cart = function () {
    boot($('cart'), g.NudgeCartPage && g.NudgeCartPage.state, ['c-checkout']);
    var note = document.querySelector('textarea'); if (note && !note.__ix) { note.__ix = 1; note.value = NS.cart.note(); note.addEventListener('input', function () { NS.cart.note(note.value); }); }
  };
  NS.integrations.drawer = function () {
    boot($('cd-body'), g.NudgeCartDrawer && g.NudgeCartDrawer.state, ['cd-checkout']);
  };
})(window);

;
/* ---- integrations/blog-links.js ---- */
/* NUDGE interactive website: Blog listing and Article integration. Article cards, tags, Journal links and Previous/Next are resolved by the route resolver. This file binds the pages to routes:
   LISTING /blogs/journal/tagged/:tag hides the cards whose article does not carry the tag (tags are a prototype assignment, see data/blog-data.js) and marks the active tag; the PLP-style empty state
   is used when no card is left. ARTICLE /blogs/journal/:handle sets the title, breadcrumb, tag links and the Previous/Next titles. The article layout is one sample article body for every handle.
   NOT POSSIBLE without new design: "related products" on an article (the Article wireframe has no such section) and pagination (the listing shows one page). Both are reported, not invented.
   In Shopify: blog.articles | tag filter via /blogs/journal/tagged/:tag, paginate, article.tags, article.metafields for related products. */
(function (g) {
  'use strict';
  var NS = g.NudgeSite;
  function cardOf(a) { return a.closest('article') || a.closest('li'); }
  NS.integrations.blog = function () {
    var q = new URLSearchParams(g.location.search), t = q.get('t'), tag = t ? NS.blog.tagFromText(t) : null; if (t && !tag) { NS.go('/404'); return; }
    if (!tag) return; document.title = tag + ' | Journal | NUDGE';
    var shown = 0, seen = [];
    [].forEach.call(document.querySelectorAll('main a[href="#article"]'), function (a) {
      var c = cardOf(a); if (!c || seen.indexOf(c) > -1) return; seen.push(c);
      var h = c.querySelector('h2,h3,h4'), art = NS.blog.byTitle(h ? h.textContent : a.textContent), ok = !!art && art.tags.indexOf(tag) > -1; c.hidden = !ok; if (ok) shown++;
    });
    [].forEach.call(document.querySelectorAll('main a[href="#tag"],main a[href="#blog"]'), function (a) { var on = NS.blog.tagFromText(a.textContent) === tag; if (on) a.setAttribute('aria-current', 'true'); else if (a.getAttribute('aria-current') === 'true') a.removeAttribute('aria-current'); });
    var all = [].filter.call(document.querySelectorAll('main a[href="#blog"]'), function (a) { return a.textContent.trim() === 'All'; })[0]; if (all) all.removeAttribute('aria-current');
    if (!shown && g.NudgeBlog) g.NudgeBlog.state('empty');
  };
  NS.integrations.article = function () {
    var q = new URLSearchParams(g.location.search), h = q.get('a') || NS.blog.articles[0].handle, art = NS.blog.get(h); if (!art) { NS.go('/404'); return; }
    var title = document.querySelector('main h1'); if (title) title.textContent = art.title; document.title = art.title + ' | Journal | NUDGE';
    NS.breadcrumbs.update([{ label: 'Home', route: '/' }, { label: 'Journal', route: '/blogs/journal' }, { label: art.title, route: '/blogs/journal/' + h }]);
    var groups = []; [].forEach.call(document.querySelectorAll('main a[href="#tag"]'), function (a) { var p = a.parentElement, g2 = groups.filter(function (x) { return x.p === p; })[0]; if (!g2) groups.push(g2 = { p: p, list: [] }); g2.list.push(a); });
    groups.forEach(function (gr) { gr.list.forEach(function (a, i) { a.textContent = art.tags[i % art.tags.length]; }); });
    var nb = NS.blog.neighbours(h);
    [['prev', nb.prev], ['next', nb.next]].forEach(function (pair) {
      var a = document.querySelector('main a[href="#' + pair[0] + '"]'); if (!a) return;
      var s = [].slice.call(a.querySelectorAll('*')).filter(function (x) { return /Sample title/.test(x.textContent) && !x.children.length; })[0]; if (s) s.textContent = pair[1].title;
    });
  };
})(window);

;
/* ---- integrations/content-links.js ---- */
/* NUDGE interactive website: content pages (Contact, FAQ, About, Story, Shipping, Returns, Privacy, Terms, 404). These pages need no binding: their in-page anchors already work and their
   cross links (Contact, FAQ, policies, Shop, Home, Journal) are resolved by the route resolver. Only the Story and About calls to action and the 404's "back to the store" links are listed here
   so the page-linking map and the tests know they were considered. Contact form and FAQ accordions keep the page's own behaviour (the contact form shows the page's own success state and sends nothing).
   In Shopify: {% form 'contact' %} posts to /contact; policy pages are shop.policies or page templates. */
(function (g) {
  'use strict';
  var NS = g.NudgeSite;
  NS.integrations.content = function () { /* intentionally empty: resolver rules cover every link on these pages */ };
})(window);

;
